/* PROPERTY FINDERS DRY-RUN ONLY. Synthetic data, no network, no CRM writes, no seller outreach. */
const leads = [
 {sourceUrl:'https://example.invalid/listing/101', address:'12 Example Road, London, AB1 2CD', askingPrice:250000, estimatedComparableValue:300000, daysListed:75, privateSellerEvidence:true, sourceVerified:true, notes:'Synthetic test record'},
 {sourceUrl:'https://example.invalid/listing/102', address:'12 Example Road, London, AB1 2CD', askingPrice:250000, estimatedComparableValue:null, daysListed:null, privateSellerEvidence:false, sourceVerified:false, notes:'Duplicate synthetic address; evidence incomplete'},
 {sourceUrl:'https://example.invalid/listing/103', address:'8 Sample Street, London, EF3 4GH', askingPrice:0, estimatedComparableValue:280000, daysListed:30, privateSellerEvidence:false, sourceVerified:false, notes:'Invalid asking price test'}
];
const seen = new Set();
return leads.map((lead) => {
 const key = String(lead.address || '').trim().toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
 const duplicate = key.length > 0 && seen.has(key);
 if (key) seen.add(key);
 const validPrice = Number.isFinite(lead.askingPrice) && lead.askingPrice > 0;
 const validComp = Number.isFinite(lead.estimatedComparableValue) && lead.estimatedComparableValue > 0;
 const discountPct = validPrice && validComp ? Math.round((1 - lead.askingPrice / lead.estimatedComparableValue) * 1000) / 10 : null;
 let confidence = lead.sourceVerified && validPrice && validComp ? 'MEDIUM' : 'LOW';
 let status = 'REVIEW_REQUIRED';
 if (!validPrice) status = 'INVALID_PRICE_REVIEW';
 else if (duplicate) status = 'POSSIBLE_DUPLICATE';
 else if (lead.sourceVerified && validComp && discountPct >= 10 && lead.privateSellerEvidence) status = 'PRIORITY_HUMAN_REVIEW';
 return {json:{project:'PROPERTY_FINDERS',sourceUrl:lead.sourceUrl,address:lead.address,askingPrice:lead.askingPrice,estimatedComparableValue:lead.estimatedComparableValue,discountPct,daysListed:lead.daysListed,privateSellerEvidence:lead.privateSellerEvidence,sourceVerified:lead.sourceVerified,duplicate,confidence,status,action:'NO_OUTREACH_NO_REFERRAL_NO_FINANCIAL_DECISION',dryRun:true,notes:lead.notes}};
});
